#!/usr/bin/env node
// Issue #254: how far are the JavaScript engine's built-in Math functions
// from the libm crate (and from the Rust std f64 methods, i.e. glibc)?
//
// Reads js/test/vectors/libm.json (generated by
// experiments/issue-254/rust-vectors/src/bin/libm.rs) and, for every
// function, counts the vectors where Math.* differs bit-for-bit from the
// libm result and from the std result, and checks the JavaScript port
// (js/src/rust/libm.js) against libm too. NaN results compare as a class
// (any NaN equals any NaN), since payloads are platform-dependent.
//
// Usage (from the repository root):
//   node experiments/issue-254/libm-compare.mjs
//   ~/.bun/bin/bun experiments/issue-254/libm-compare.mjs
//   npx -y node@20 experiments/issue-254/libm-compare.mjs

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import * as port from '../../js/src/rust/libm.js';

const vectorsPath = fileURLToPath(new URL('../../js/test/vectors/libm.json', import.meta.url));
const { functions } = JSON.parse(readFileSync(vectorsPath, 'utf8'));

const f64 = new Float64Array(1);
const u64 = new BigUint64Array(f64.buffer);

/** @param {string} hex */
function fromHex(hex) {
  u64[0] = BigInt(`0x${hex}`);
  return f64[0];
}

/** @param {number} x */
function toHex(x) {
  f64[0] = x;
  return u64[0].toString(16).padStart(16, '0');
}

/** Same bits, or both NaN. */
function same(a, b) {
  return a === b || (Number.isNaN(fromHex(a)) && Number.isNaN(fromHex(b)));
}

/** @type {Record<string, (...args: number[]) => number>} */
const builtin = {
  sin: Math.sin,
  cos: Math.cos,
  tan: Math.tan,
  asin: Math.asin,
  acos: Math.acos,
  atan: Math.atan,
  atan2: Math.atan2,
  sinh: Math.sinh,
  cosh: Math.cosh,
  tanh: Math.tanh,
  exp: Math.exp,
  log: Math.log,
  log10: Math.log10,
  log2: Math.log2,
  pow: Math.pow,
  cbrt: Math.cbrt,
  sqrt: Math.sqrt,
  // JavaScript has no fused multiply-add: the best it offers is a * b + c.
  fma: (a, b, c) => a * b + c,
};

const runtime =
  typeof globalThis.Bun !== 'undefined'
    ? `Bun ${globalThis.Bun.version}`
    : `Node ${process.versions.node} (V8 ${process.versions.v8})`;

const rows = [];
let total = 0;
for (const [name, vectors] of Object.entries(functions)) {
  const fn = builtin[name];
  let vsLibm = 0;
  let vsStd = 0;
  let stdVsLibm = 0;
  let portVsLibm = 0;
  const examples = [];
  for (const row of vectors) {
    const args = row.slice(0, -2).map(fromHex);
    const libm = row[row.length - 2];
    const std = row[row.length - 1];
    const got = toHex(fn(...args));
    if (!same(got, libm)) {
      vsLibm++;
      if (examples.length < 2) examples.push(`${name}(${row.slice(0, -2).join(', ')}) = ${got}, libm ${libm}`);
    }
    if (!same(got, std)) vsStd++;
    if (!same(std, libm)) stdVsLibm++;
    if (!same(toHex(port[name](...args)), libm)) portVsLibm++;
  }
  total += vectors.length;
  rows.push({ name, vectors: vectors.length, vsLibm, vsStd, stdVsLibm, portVsLibm, examples });
}

console.log(`# ${runtime}: Math.* against libm 0.2.16 and Rust std (glibc)\n`);
console.log('| function | vectors | Math vs libm | Math vs std | std vs libm | port vs libm |');
console.log('| --- | ---: | ---: | ---: | ---: | ---: |');
for (const r of rows) {
  console.log(`| ${r.name} | ${r.vectors} | ${r.vsLibm} | ${r.vsStd} | ${r.stdVsLibm} | ${r.portVsLibm} |`);
}
console.log(`\n${total} vectors in total.\n`);
for (const r of rows) {
  for (const e of r.examples) console.log(`  e.g. ${e}`);
}
